func (this *Table) deselectAll_(id int64, sel int64, sender int64) {
	if this.preventSelect && !this.ignoreSelect {
		return
	}
	if (this.style&SINGLE) != 0 && !this.ignoreSelect {
		if (castcocoaNSViewTococoaNSTableView(this.View)).SelectedRow() != -1 {
			return
		}
	}
	this.Composite.deselectAll_(id, sel, sender)
}

func (this *Table) deselectRow_(id int64, sel int64, index int64) {
	if this.preventSelect && !this.ignoreSelect {
		return
	}
	if (this.style&SINGLE) != 0 && !this.ignoreSelect {
		if (castcocoaNSViewTococoaNSTableView(this.View)).SelectedRow() == index {
			return
		}
	}
	this.Composite.deselectRow_(id, sel, index)
}
